import select from './select/yds-select.twig';
import textfields from './textfields/yds-textfields.twig';
import formExample from './contact-form-example.twig';

import selectOptionsData from './select/select.yml';
import viewsFilterForm from './views-filter/_yds-views-filter-form.twig';
import filterData from './views-filter/views-filter.yml';
import './views-filter/chosen-base.css';

import {
  globalThemeLabels,
  globalThemes,
  sectionThemes,
} from '../../_storybook/theme-constants';
import { createGlobalThemeStories } from '../../_storybook/global-theme-stories.mjs';
import {
  createSectionWrapper,
  createThemeVariations,
} from '../../_storybook/playground-utils';

export default {
  tags: ['visreg'],
  title: 'Atoms/Forms/Visreg',
  parameters: {
    chromatic: { disableSnapshot: false },
    controls: { disable: true },
  },
};

const renderGlobalTheme = () => {
  const buttonTheme = 'one';

  // Render function for form variations
  const renderForms = (theme) =>
    createSectionWrapper(
      theme,
      `
          <h3>Select Dropdowns</h3>
          ${select(selectOptionsData)}

          <h3>Text Fields</h3>
          ${textfields()}

          <h3>Example Form</h3>
          ${formExample({ buttonTheme })}
        `,
    );

  return createThemeVariations(
    renderForms,
    sectionThemes,
    'All Section Theme Variations',
    'Below are all theme variations for visual regression testing.',
    'Section Theme',
  );
};

const themeStories = createGlobalThemeStories(
  renderGlobalTheme,
  globalThemes,
  globalThemeLabels,
);

export const OldBlues = themeStories.one;
export const NewHavenGreen = themeStories.two;
export const ShorelineSummer = themeStories.three;
export const Onha = themeStories.four;
export const ItsYourYale = themeStories.five;
export const AI = themeStories.six;
export const WhitneyHumanitiesCenter = themeStories.seven;

ItsYourYale.storyName = 'It’s Your Yale';

/**
 * The Views filters use fixed tokens (gray, blue-horizon, white), not theme
 * colors, so they do not vary by global theme. They get stories of their own
 * rather than being repeated in every global theme story.
 */
const { categories, audiences, longVocabularyName, longTerms } = filterData;

const filterField =
  (id, label, options) =>
  (extra = {}) => ({ id, label, options, selected: [], ...extra });
const category = filterField('category', 'Category', categories);
const audience = filterField('audience', 'Audience', audiences);
const longVocabulary = filterField('long', longVocabularyName, longTerms);
// A filter with no terms: Chosen disables it and shows "No options available."
const emptyFilter = (extra = {}) =>
  filterField('empty', 'Topic', [])({ disabled: true, ...extra });

const form = (props) => viewsFilterForm({ search: '', ...props });
const heading = (text) => `<h3>${text}</h3>`;
// The open list is absolutely positioned; leave room so it is not cut off.
const room = (markup) => `<div style="padding-bottom: 18rem">${markup}</div>`;

// Closed with no selection (Category) and closed with two chips (Audience),
// then five chips (Category) where only the first fits on the row. The rest
// collapse into the "+4 more" badge. yds-select.js does that measuring on a
// site; visible: 1 was measured at the four-column, ~233px track of the grid.
export const ViewsFiltersClosed = () =>
  createSectionWrapper(
    'default',
    heading('Closed: none selected, then two chips, then "+4 more"') +
      form({
        id: 'closed',
        fields: [category(), audience({ selected: ['Faculty', 'Staff'] })],
      }) +
      form({
        id: 'closed-more',
        fields: [
          category({
            selected: ['Featured', 'About', 'Research', 'Academics', 'Contact'],
            visible: 1,
          }),
          audience(),
        ],
      }),
  );

export const ViewsFiltersOpenWithTwoSelected = () =>
  createSectionWrapper(
    'default',
    heading('Open with two chips') +
      room(
        form({
          id: 'open',
          fields: [
            category({
              open: true,
              selected: ['Featured', 'Page Category 1'],
              visible: 1,
            }),
            audience(),
          ],
        }),
      ),
  );

export const ViewsFiltersLongVocabularyName = () =>
  createSectionWrapper(
    'default',
    heading('Long vocabulary name: one chip and "+1 more", closed and open') +
      room(
        form({
          id: 'long',
          fields: [
            // Two long terms overflow the row; the real JS keeps one chip.
            longVocabulary({ selected: longTerms.slice(0, 2), visible: 1 }),
            longVocabulary({
              id: 'long-open',
              open: true,
              selected: longTerms.slice(0, 2),
              // Open keeps the closed one-line row and badge. (#1930)
              visible: 1,
            }),
          ],
        }),
      ),
  );

// A filter row with one empty filter between filled ones, to check the empty
// box matches its neighbors' width, height, and border. (#1832)
export const ViewsFiltersEmpty = () =>
  createSectionWrapper(
    'default',
    heading('Empty filter next to filled ones') +
      form({
        id: 'empty',
        fields: [
          category({ selected: ['Featured', 'Page Category 1'] }),
          emptyFilter(),
          audience(),
        ],
      }),
  );

// A box about 9rem wide cannot fit "No options available.", so it cuts off
// with "...". The wrapper narrows the grid column, as a small screen would.
export const ViewsFiltersEmptyNarrow = () => {
  const narrowForm = form({
    id: 'empty-narrow',
    hide_search: true,
    fields: [emptyFilter()],
  });
  return createSectionWrapper(
    'default',
    `${heading(
      'Empty filter in a narrow box: text cut off with "..."',
    )}<div style="max-width: 9rem">${narrowForm}</div>`,
  );
};

const calendarFields = (id) => [
  category({ id: `${id}-category` }),
  audience({ id: `${id}-audience`, selected: ['Faculty', 'Staff'] }),
  longVocabulary({ id: `${id}-custom` }),
];

export const ViewsFiltersEventsCalendar = () =>
  createSectionWrapper(
    'default',
    heading('Events calendar filters') +
      form({
        id: 'calendar',
        calendar: true,
        search: 'Search events',
        fields: calendarFields('calendar'),
      }) +
      heading('Events calendar filters with one empty filter') +
      form({
        id: 'calendar-empty',
        calendar: true,
        search: 'Search events',
        fields: [
          category({ id: 'calendar-empty-category' }),
          emptyFilter({ id: 'calendar-empty-topic' }),
          audience({ id: 'calendar-empty-audience' }),
        ],
      }),
  );

// Both forms are a CSS grid whose columns are at least 13rem wide, so at 375px
// they collapse to one column. Below $break-mobile (992px) the Events calendar
// form also forces its items to 100% width, and Chosen containers get a black
// border. A narrow wrapper would not trigger the media query, so this story
// needs a phone-width snapshot.
//
// The shared styles set `overflow-x: hidden` on html and body (tokens.css,
// page-layouts.css). That makes overflow-y compute to `auto`, so at narrow
// widths the body becomes its own scroll box inside Chromatic's 900px window
// and the snapshot stops partway down. The <style> below lets the page grow to
// its full height so the whole page, down to the Apply button, is captured.
export const ViewsFiltersPhoneWidth = () =>
  `<style>html, body { overflow: visible; }</style>${createSectionWrapper(
    'default',
    heading('Views filters at 375px (one column)') +
      form({
        id: 'phone',
        fields: [
          category({ selected: ['Featured', 'Page Category 1'] }),
          emptyFilter(),
          audience(),
        ],
      }) +
      heading('Events calendar filters at 375px (stacked)') +
      form({
        id: 'phone-calendar',
        calendar: true,
        search: 'Search events',
        fields: calendarFields('phone-calendar'),
      }),
  )}`;
ViewsFiltersPhoneWidth.parameters = {
  ...ViewsFiltersPhoneWidth.parameters,
  chromatic: { viewports: [375] },
};

// Filter bar layout by filter count (YaleSites-Internal#2184): search first and
// at least half the row, no partly empty row. The bar sizes itself to its own
// width, so each count is shown in a wide, a medium and a narrow wrapper.
const countedFilters = (id, count) =>
  Array.from({ length: count }, (_, i) =>
    category({ id: `${id}-f${i}`, label: `Filter ${i + 1}` }),
  );
const counts = [0, 1, 2, 3, 4, 5, 6, 7, 8];
const countedForms = (prefix, props = {}) =>
  counts
    .map(
      (n) =>
        heading(`${n} filter${n === 1 ? '' : 's'}`) +
        form({
          id: `${prefix}-${n}`,
          fields: countedFilters(`${prefix}-${n}`, n),
          ...props,
        }),
    )
    .join('');
const widthBox = (width, markup) =>
  `<div style="width: ${width}; max-width: 100%">${markup}</div>`;

export const ViewsFiltersLayoutWide = () =>
  createSectionWrapper(
    'default',
    widthBox('62rem', countedForms('wide')) +
      heading('Search off, 1 to 8 filters') +
      widthBox('62rem', countedForms('wide-nosearch', { hide_search: true })),
  );

export const ViewsFiltersLayoutMedium = () =>
  createSectionWrapper('default', widthBox('40rem', countedForms('mid')));

export const ViewsFiltersLayoutNarrow = () =>
  createSectionWrapper('default', widthBox('24rem', countedForms('narrow')));
